using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Library.Web.Models;using Library.Web.Services;
namespace Library.Web.Pages.Members;
public sealed class IndexModel:PageModel{private readonly LibraryStore _store;public IReadOnlyList<Member> Members{get;private set;}=[];[BindProperty]public Member NewMember{get;set;}=new();[BindProperty]public Member EditMember{get;set;}=new();public string? ErrorMessage{get;private set;}public IndexModel(LibraryStore store)=>_store=store;public void OnGet()=>Load();public IActionResult OnPostCreate(){if(string.IsNullOrWhiteSpace(NewMember.MemberNumber)||string.IsNullOrWhiteSpace(NewMember.FullName)||string.IsNullOrWhiteSpace(NewMember.YearLevel)){ErrorMessage="Student ID, full name, and year level are required.";Load();return Page();}try{_store.AddMember(NewMember);return RedirectToPage();}catch(Exception ex){ErrorMessage=ex.Message;Load();return Page();}}public IActionResult OnPostUpdate(int id){try{var existing=_store.GetMember(id);if(existing is null){ErrorMessage="Student not found.";Load();return Page();}EditMember.MemberId=id;EditMember.MemberNumber ??= existing.MemberNumber;EditMember.Course ??= existing.Course;EditMember.Status ??= existing.Status;EditMember.FullName=EditMember.FullName.Trim();_store.UpdateMember(EditMember);return RedirectToPage();}catch(Exception ex){ErrorMessage=ex.Message;Load();return Page();}}public IActionResult OnPostDelete(int id){try{_store.DeleteMember(id);return RedirectToPage();}catch(Exception ex){ErrorMessage=ex.Message;Load();return Page();}}private void Load()=>Members=_store.Members;}
